def caesar_cipher_encrypt(text, shift):
    res = ""
    alph_len = 26
    for curr in text:
        if 'a' <= curr <= 'z':
            pos = ord(curr) - ord('a')
            new_pos = (pos + shift) % alph_len
            res += chr(ord('a') + new_pos)
        elif 'A' <= curr <= 'Z':
            idx = ord(curr) - ord('A')
            val = (idx + shift) % alph_len
            res += chr(ord('A') + val)
        else:
            res += curr
    return res

