def validate_email(email):
    if not isinstance(email, str):
        return False

    idx_at = email.find('@')
    idx_dot = email.rfind('.')

    if idx_at == -1 or idx_dot == -1:
        return False

    if idx_at > idx_dot:
        return False

    if idx_at == 0 or idx_dot == len(email) - 1:
        return False

    res = True
    curr_char = ''
    prev_char = ''
    for pos, curr_char in enumerate(email):
        if curr_char in ('@', '.'):
            if pos == 0 or pos == len(email) - 1:
                res = False
                break
            if prev_char in ('@', '.'):
                res = False
                break
        prev_char = curr_char
    return res

