            current_position = ord(current_character) - ord('a')
            previous_position = (current_position - shift + alphabet_size) % alphabet_size
            decrypted_character = chr(previous_position + ord('a'))
            result_characters.append(decrypted_character)
        else:
            result_characters.append(current_character)
    result_message = "".join(result_characters)
    return result_message

