def decimal_to_hex(dec_num):
    if dec_num == 0:
        return '0'
    hex_map = "0123456789ABCDEF"
    res = []
    curr = dec_num
    while curr > 0:
        rem = curr % 16
        res.append(hex_map[rem])
        curr //= 16
    return "".join(res[::-1])

