def is_brackets_balanced(s: str) -> bool:
    stk = []
    map_open = {"(": ")", "[": "]", "{": "}"}
    for curr in s:
        if curr in map_open:
            stk.append(curr)
        else:
            if not stk:
                return False
            prev_open = stk.pop()
            if map_open[prev_open] != curr:
                return False
    res = not stk
    return res

