def calculate_power(base, exponent):
    if exponent == 0:
        return 1

    is_neg_exp = exponent < 0
    abs_exp = abs(exponent)

    res = 1.0 if isinstance(base, float) else 1
    curr_base = base

    while abs_exp > 0:
        if abs_exp % 2 == 1:
            res *= curr_base
        curr_base *= curr_base
        abs_exp //= 2

    if is_neg_exp:
        return 1 / res
    else:
        return res

