        if amount <= 0:
            return False
        if self.balance < amount:
            return False
        current_balance = self.balance # Current balance check
        result_withdraw = self.withdraw(amount)
        if not result_withdraw:
            return False
        result_deposit = target_account.deposit(amount)
        if not result_deposit:
            # If deposit fails, revert the withdrawal
            self.deposit(amount)
            return False
        return True

    def get_status_message(self):
