    low_idx = 0
    high_idx = len(sorted_lst) - 1

    while low_idx <= high_idx:
        mid_pos = (low_idx + high_idx) // 2
        curr_elem = sorted_lst[mid_pos]

        if curr_elem == search_val:
            return mid_pos
        elif curr_elem < search_val:
            low_idx = mid_pos + 1
