import re

def extract_domain(url_str):
    reg = r'^(?:https?://)?(?:www\.)?([a-zA-Z0-9-]+)(?:\.[a-zA-Z0-9-.]+){1,}'
    mtch = re.search(reg, url_str)
    if mtch:
        res_domain = mtch.group(1)
        return res_domain
    else:
        return ""

def process_urls(url_list_param):
    final_results = []
    for curr_url_idx, curr_url_val in enumerate(url_list_param):
        extracted_name = extract_domain(curr_url_val)
        if extracted_name:
            final_results.append(extracted_name)
        else:
            err_msg = f"Failed to extract from URL at index {curr_url_idx}"
            print(err_msg)
    return final_results

