import re

def extract_domain(url_string):
    regular_expression = r'^(?:https?://)?(?:www\.)?([a-zA-Z0-9-]+)(?:\.[a-zA-Z0-9-.]+){1,}'
    match = re.search(regular_expression, url_string)
    if match:
        result_domain = match.group(1)
        return result_domain
    else:
        return ""

def process_urls(url_list_parameter):
    final_results = []
    for current_url_index, current_url_value in enumerate(url_list_parameter):
