import datetime

def get_next_business_day(curr_date):
    day_idx = curr_date.weekday()
    if day_idx < 4:  # Monday (0) to Thursday (3)
        res_date = curr_date + datetime.timedelta(days=1)
    elif day_idx == 4:  # Friday (4)
        res_date = curr_date + datetime.timedelta(days=3)
    else:  # Saturday (5) or Sunday (6)
        days_to_add = 7 - day_idx + 1 if day_idx == 5 else 1
        res_date = curr_date + datetime.timedelta(days=days_to_add)
    return res_date

