def geometric_series_sum(a, r, n_terms):
    if n_terms <= 0:
        return 0.0

    if r == 1:
        res = a * n_terms
        return float(res)
    else:
        num = a * (1 - r**n_terms)
        den = 1 - r
        val = num / den
        return float(val)

