def geometric_series_sum(initial_term, common_ratio, number_of_terms):
    if number_of_terms <= 0:
        return 0.0

    if common_ratio == 1:
        result = initial_term * number_of_terms
        return float(result)
    else:
        numerator = initial_term * (1 - common_ratio**number_of_terms)
        denominator = 1 - common_ratio
        value = numerator / denominator
        return float(value)

