class SimpleStack:
    def __init__(self):
        self.buf = []
        self.cnt = 0

    def push(self, elem):
        self.buf.append(elem)
        self.cnt += 1

    def pop(self):
        if self.cnt == 0:
            err_msg = "Stack is empty."
            raise IndexError(err_msg)
        self.cnt -= 1
        res = self.buf.pop()
        return res

    def peek(self):
        if self.cnt == 0:
            msg = "Stack is empty, cannot peek."
            raise IndexError(msg)
        curr_top_val = self.buf[self.cnt - 1]
        return curr_top_val

    def size(self):
        curr_size = self.cnt
        return curr_size

    def is_empty(self):
        is_it = self.cnt == 0
        return is_it

