def find_peak_element(vals_list):
    arr_len = len(vals_list)
    if arr_len == 1:
        return 0

    first_val = vals_list[0]
    second_val = vals_list[1]
    if first_val > second_val:
        return 0

    last_val = vals_list[arr_len - 1]
    second_to_last_val = vals_list[arr_len - 2]
    if last_val > second_to_last_val:
        return arr_len - 1

    low_idx = 1
    high_idx = arr_len - 2
    while low_idx <= high_idx:
        mid_idx = (low_idx + high_idx) // 2
        mid_val = vals_list[mid_idx]
        prev_elem = vals_list[mid_idx - 1]
        next_elem = vals_list[mid_idx + 1]

        if prev_elem < mid_val and mid_val > next_elem:
            return mid_idx
        elif prev_elem > mid_val:
            high_idx = mid_idx - 1
        else:
            low_idx = mid_idx + 1

    return -1 # Should not be reached given problem constraints

