def is_perfect_square(n: int) -> bool:
    if n < 0:
        return False

    if n == 0:
        return True

    low_bound = 1
    high_bound = n

    while low_bound <= high_bound:
        mid_val = (low_bound + high_bound) // 2
        sq_res = mid_val * mid_val

        if sq_res == n:
            return True
        elif sq_res < n:
            low_bound = mid_val + 1
        else:
            high_bound = mid_val - 1

    return False

