class SimpleQueue:
    def __init__(self):
        self._buf = []
        self._curr_size = 0

    def enqueue(self, elem):
        self._buf.append(elem)
        self._curr_size += 1

    def dequeue(self):
        if self._curr_size == 0:
            return None

        val_to_return = self._buf.pop(0)
        self._curr_size -= 1
        return val_to_return

    def peek(self):
        if self._curr_size == 0:
            return None

        first_elem = self._buf[0]
        return first_elem

    def size(self):
        return self._curr_size

    def is_empty(self):
        return self._curr_size == 0

