def is_valid_isbn10(isbn_str):
    if len(isbn_str) != 10:
        return False

    curr_sum = 0
    curr_pos = 1

    for char_elem in isbn_str:
        if '0' <= char_elem <= '9':
            val_digit = int(char_elem)
        elif char_elem == 'X' and curr_pos == 10:
            val_digit = 10
        else:
            return False

        curr_sum += val_digit * curr_pos
        curr_pos += 1

    res_valid = (curr_sum % 11 == 0)
    return res_valid

