def is_palindromic_permutation(s_input):
    """
    Checks if a string is a permutation of a palindrome. Ignores spaces and case.
    """
    char_cnt = {}
    buf = s_input.lower()
    for char_val in buf:
        if 'a' <= char_val <= 'z':
            char_cnt[char_val] = char_cnt.get(char_val, 0) + 1

    odd_freq_count = 0
    for key_char, freq_num in char_cnt.items():
        if freq_num % 2 != 0:
            odd_freq_count += 1

    final_res = odd_freq_count <= 1
    return final_res

