def is_sorted_ascending(numbers):
    cnt = len(numbers)
    if cnt <= 1:
        return True

    prev = numbers[0]
    for idx in range(1, cnt):
        curr = numbers[idx]
        if curr < prev:
            return False
        prev = curr
    return True

