def to_pig_latin(orig_word):
    vowels_str = "aeiouAEIOU"
    first_char = orig_word[0]
    if first_char in vowels_str:
        return orig_word + "way"
    else:
        cnt = 0
        for char_val in orig_word:
            if char_val not in vowels_str:
                cnt += 1
            else:
                break

        prefix = orig_word[:cnt]
        rem_str = orig_word[cnt:]
        res = rem_str + prefix + "ay"
        return res

